#include <bits/stdc++.h>
using namespace std;

long long powerMod(long long base, long long exp, long long mod) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m;
    int L, R;
    cin >> n >> m >> L >> R;
    long long mod = 998244353;
    long long inv2 = powerMod(2, mod - 2, mod);
    long long diff = R - L + 1;
    long long p1 = diff / 2;
    long long p2 = diff - p1;
    long long answer;

    if ((n * m) % 2 == 1) {
        answer = powerMod(diff, n * m, mod);
    } else {
        long long p1Total = diff;
        long long p2Total = abs(p1 - p2);
        long long option1 = powerMod(p1Total, n * m, mod);
        long long option2 = powerMod(p2Total, n * m, mod);
        long long total = (option1 + option2) % mod;
        answer = (total * inv2) % mod;
    }
    cout << answer << "\n";
    return 0;
}

